// Constant-time multiexp on Selene and Helios points (monerodato.2's patched field).
// Part 1: each Straus and Pippenger window against the multiexp crate's own choice, per length.
// Part 2: Straus(4) split into k chunks on k threads (std::thread::scope), summed; k = 1, 2, 4.
// Prints CSV: curve,n,alg,window,median_us,reps (alg "par4t" etc. in part 2, window = 4).
use std::time::Instant;
use ff::Field;
use group::Group;
use rand_core::OsRng;
use helioselene::{SelenePoint, HeliosPoint};
use multiexp::{straus::{straus, straus_vartime}, pippenger::{pippenger, pippenger_vartime}, multiexp as auto_multiexp, multiexp_vartime as auto_vartime};

fn med(mut v: Vec<f64>) -> f64 { v.sort_by(|a, b| a.partial_cmp(b).unwrap()); v[v.len() / 2] }

fn par_straus<G>(pairs: &[(G::Scalar, G)], k: usize) -> G
where G: Group + zeroize::Zeroize + subtle::ConditionallySelectable + Send + Sync, G::Scalar: ff::PrimeFieldBits + zeroize::Zeroize + Send + Sync {
  if k <= 1 || pairs.len() < 2 * k { return straus(pairs, 4); }
  let chunk = pairs.len().div_ceil(k);
  std::thread::scope(|s| {
    let hs: Vec<_> = pairs.chunks(chunk).map(|c| s.spawn(move || if c.len() == 1 { c[0].1 * c[0].0 } else { straus(c, 4) })).collect();
    hs.into_iter().map(|h| h.join().unwrap()).fold(G::identity(), |a, b| a + b)
  })
}

fn run<G>(curve: &str, sizes: &[usize], part: u8)
where G: Group + zeroize::Zeroize + subtle::ConditionallySelectable + Send + Sync, G::Scalar: ff::PrimeFieldBits + zeroize::Zeroize + Send + Sync {
  for &n in sizes {
    let pairs: Vec<(G::Scalar, G)> = (0 .. n).map(|_| (G::Scalar::random(&mut OsRng), G::random(&mut OsRng))).collect();
    let reps = (20_000 / n).clamp(3, 41);
    let reference = auto_multiexp(&pairs);
    let time = |name: &str, w: u8, f: &dyn Fn() -> G| {
      let mut t = Vec::with_capacity(reps);
      for _ in 0 .. reps { let a = Instant::now(); let r = f(); t.push(a.elapsed().as_secs_f64() * 1e6); assert!(r == reference); }
      println!("{curve},{n},{name},{w},{:.1},{reps}", med(t));
    };
    if part == 3 && curve == "selene" {
      time("vt_auto", 0, &|| auto_vartime(&pairs));
      for w in 2 ..= 6u8 { time("vt_straus", w, &|| straus_vartime(&pairs, w)); }
      for w in 2 ..= 8u8 { if n >= 16 { time("vt_pippenger", w, &|| pippenger_vartime(&pairs, w)); } }
    } else if part == 1 || part == 3 {
      time("auto", 0, &|| auto_multiexp(&pairs));
      for w in 2 ..= 6u8 { time("straus", w, &|| straus(&pairs, w)); }
      for w in 2 ..= 8u8 { if n >= 16 { time("pippenger", w, &|| pippenger(&pairs, w)); } }
    } else {
      for k in [1usize, 2, 4] { time(&format!("par{k}t"), 4, &|| par_straus(&pairs, k)); }
    }
  }
}

fn main() {
  let part: u8 = std::env::args().nth(1).map(|a| a.parse().unwrap()).unwrap_or(1);
  println!("curve,n,alg,window,median_us,reps");
  if part == 3 {
    // constant-time on ed25519 (one of the curves the thresholds came from), and variable-time on Selene
    let sizes = [16usize, 64, 128, 256, 512, 1024, 2048];
    run::<dalek_ff_group::EdwardsPoint>("ed25519", &sizes, part);
    run::<SelenePoint>("selene", &sizes, part);
    return;
  }
  let sizes = [4usize, 8, 16, 32, 64, 128, 256, 512, 1024, 2048];
  run::<SelenePoint>("selene", &sizes, part);
  run::<HeliosPoint>("helios", &sizes, part);
}
